export class VenuesService {
  readonly #db: Db;
  readonly #venues: VenuesRepository;
  readonly #cache: TtlCache<number, Venue>;

  constructor(deps: VenuesServiceDeps) {
    this.#db = deps.db;
    this.#venues = deps.venues;
    this.#cache = deps.cache ?? new TtlCache({ ttlMs: 60_000, maxEntries: 500 });
  }

  list(): Promise<Venue[]> {
    return this.#venues.list(this.#db);
  }

  async get(id: number): Promise<Venue> {
    const cached = this.#cache.get(id);
    if (cached !== undefined) return cached;
    const venue = await this.#venues.findById(this.#db, id);
    if (venue === null) throw new NotFoundError(`No venue with id ${id}`);
    this.#cache.set(id, venue);
    return venue;
  }

  create(input: CreateVenue): Promise<Venue> {
    return this.#venues.create(this.#db, input);
  }

  async update(id: number, changes: UpdateVenue): Promise<Venue> {
    const venue = await this.#venues.update(this.#db, id, changes);
    if (venue === null) throw new NotFoundError(`No venue with id ${id}`);
    // Without this, GET would serve the old name until the entry expired.
    this.#cache.delete(id);
    return venue;
  }
}

export interface VenuesRepository {
  list(db: DbOrTx): Promise<Venue[]>;
  findById(db: DbOrTx, id: number): Promise<Venue | null>;
  create(db: DbOrTx, venue: NewVenue): Promise<Venue>;
  /** The updated venue, or null when there is none with this id. */
  update(db: DbOrTx, id: number, changes: Partial<NewVenue>): Promise<Venue | null>;
}

// A second "Riverside Hall" in the same city is a mistake the database refuses.
function translateDuplicate(err: unknown): never {
  if (pgErrorCode(err) === "23505" && pgConstraint(err) === "venues_name_city_unique") {
    throw new ConflictError("venue-exists", "A venue with this name already exists in this city");
  }
  throw err;
}

export const venuesRepository: VenuesRepository = {
  async list(db) {
    return db.select().from(venues).orderBy(asc(venues.city), asc(venues.name), asc(venues.id));
  },

  async findById(db, id) {
    const [venue] = await db.select().from(venues).where(eq(venues.id, id));
    return venue ?? null;
  },

  async create(db, venue) {
    try {
      const [created] = await db.insert(venues).values(venue).returning();
      return created as Venue;
    } catch (err) {
      return translateDuplicate(err);
    }
  },
  // ...
};

/** Puts a draft on sale. It needs a future start time and at least one ticket type. */
async publish(user: AuthUser, eventId: number): Promise<EventWithVenue> {
  const { db, events, ticketTypes, hooks } = this.#deps;
  await withTx(db, async (tx) => {
    const event = await this.#lockEditable(tx, user, eventId);
    if (event.status !== "draft") {
      throw new ConflictError("event-not-draft", `Only a draft can be published, and this event is ${event.status}`);
    }
    if (event.startsAt <= now()) throw new ConflictError("event-in-past", "This event has already started");
    if ((await ticketTypes.listForEvent(tx, eventId)).length === 0) {
      throw new ConflictError("no-ticket-types", "Add at least one ticket type before publishing");
    }
    const published = await events.update(tx, eventId, { status: "published", publishedAt: now() });
    await hooks.run("event.published", { event: published, actor: user }, tx);
  });
  return this.get(user, eventId);
}

export function createServices(deps: ServiceDeps): {
  services: Services;
  hooks: HookRegistry;
  tokens: TokenService;
  posters: PosterStorage;
} {
  const { db, repositories: repos, config, logger } = deps;

  const hooks = new HookRegistry();
  registerEventHooks(hooks, { events: repos.events });
  registerAuditHooks(hooks, new AuditService(repos.audit));

  const tokens = new TokenService(config.jwt);
  const posters = deps.posters ?? new PosterStorage(config.uploadDir);

  const services: Services = {
    auth: new AuthService({
      db,
      users: repos.users,
      refreshTokens: repos.refreshTokens,
      passwords: deps.passwords ?? new PasswordHasher(),
      tokens,
      refreshTokenTtlDays: config.refreshTokenTtlDays,
    }),
    venues: new VenuesService({ db, venues: repos.venues }),
    // ...
  return { services, hooks, tokens, posters };
}

